// 1. 直接從 Line Messaging Trigger 取得原始文字
// 使用 .first() 確保抓到第一筆資料
const rawInput = $("Line Messaging Trigger").first().json.message.text;

if (!rawInput) {
    throw new Error("找不到輸入文字，請確認 Line Trigger 節點連線正確。");
}

// 2. 清理字串：轉大寫、移除「飛機」關鍵字、移除所有空格
// 例如：「飛機 EK366」 -> 「EK366」
const flightRaw = rawInput
    .toUpperCase()
    .replace(/[飛機]/g, "") // 這裡會過濾掉「飛」和「機」這兩個字
    .replace(/\s+/g, "");   // 移除所有空格

// 3. 拆分代碼 (前2碼為航空公司，例如 EK; 後面為數字，例如 366)
const airlineID = flightRaw.substring(0, 2);
const flightNumber = flightRaw.substring(2);

// 4. 安全檢查：如果拆分後長度不足 (至少要 2碼ID + 1碼數字)，則噴錯
if (flightRaw.length < 3 || !airlineID || !flightNumber) {
    throw new Error(`無法解析航班號碼，原始輸入：${rawInput}`);
}

return {
    airline_id: airlineID,
    flight_number: flightNumber,
    // 準備好 TDX 的過濾語法
    tdx_filter: `AirlineID eq '${airlineID}' and FlightNumber eq '${flightNumber}'`,
    original_text: rawInput
};

const items = $input.all();

// 1. 取得 Reply Token
let replyToken = "";
try {
  replyToken = $('Line Messaging Trigger').item.json.replyToken;
} catch (e) {
  replyToken = $json.replyToken || "";
}

// --- 基礎資料對照表 ---
const airlineMap = { 
  'EK': '阿聯酋航空', 'JX': '星宇航空', 'CI': '中華航空', 
  'BR': '長榮航空', 'CX': '國泰航空', 'JL': '日本航空', 
  'NH': '全日空', 'IT': '台灣虎航', 'TR': '酷航' 
};
const airportMap = { 
  'TPE': '桃園', 'HKG': '香港', 'DXB': '杜拜', 
  'NRT': '成田', 'NGO': '名古屋', 'KIX': '關西', 
  'SIN': '新加坡', 'ICN': '首爾' 
};

// 2. 查無航班處理
if (items.length === 0 || !items[0].json.FlightNumber) {
  return {
    replyToken: replyToken,
    flexMessage: {
      type: "flex",
      altText: "查無航班資訊",
      contents: {
        type: "bubble",
        body: {
          type: "box", layout: "vertical", contents: [
            { type: "text", text: "⚠️ 查無此航班資訊", weight: "bold", size: "xl", color: "#ff4444" }
          ]
        }
      }
    }
  };
}

// 3. 處理邏輯
const dailyGroups = new Map();
const airlineID = items[0].json.AirlineID;
const flightNum = items[0].json.FlightNumber;
const mainAirlineName = airlineMap[airlineID] || items[0].json.AirlineName?.Zh_tw || airlineID;

for (const item of items) {
  const f = item.json;
  const isArrival = f.ArrivalAirportID === 'TPE';

  const depName = airportMap[f.DepartureAirportID] || f.DepartureAirportID;
  const arrName = airportMap[f.ArrivalAirportID] || f.ArrivalAirportID;
  const scheduleStr = isArrival ? f.ScheduleArrivalTime : f.ScheduleDepartureTime;
  const schedDate = (scheduleStr || "").substring(5, 10).replace('-', '/');

  let timeStr = isArrival 
    ? (f.ActualArrivalTime || f.EstimatedArrivalTime || f.ScheduleArrivalTime)
    : (f.ActualDepartureTime || f.EstimatedDepartureTime || f.ScheduleDepartureTime);

  let statusColor = "#17c06b"; 
  let statusLabel = "表定";
  const remark = f.ArrivalRemark || f.DepartureRemark || '正常';

  if (remark.includes("取消") || remark.includes("延遲") || remark.includes("DELAY")) {
    statusColor = "#ef4d4d"; 
  } else if (remark.includes("出發") || remark.includes("到達") || remark.includes("ARRIVED")) {
    statusColor = "#666666"; 
  }

  if (isArrival) {
    if (f.ActualArrivalTime) statusLabel = "實際";
    else if (f.EstimatedArrivalTime) statusLabel = "預計";
  } else {
    if (f.ActualDepartureTime) statusLabel = "實際";
    else if (f.EstimatedDepartureTime) statusLabel = "預計";
  }

  let displayTime = (timeStr || "").substring(11, 16);
  const actualDate = (timeStr || "").substring(5, 10).replace('-', '/');
  if (schedDate && actualDate && schedDate !== actualDate) {
    displayTime += ` (${actualDate})`;
  }

  const codeshare = f.AirlineID2 ? ` (聯營: ${airlineMap[f.AirlineID2] || f.AirlineID2}${f.FlightNumber2})` : "";

  // 字體調大版佈局
  const flightRow = {
    type: "box", layout: "vertical", spacing: "md", paddingAll: "20px", contents: [
      { type: "text", text: `${isArrival ? '🛬 抵達' : '🛫 出發'} · ${remark}`, weight: "bold", size: "md", color: statusColor },
      { type: "text", text: `${depName} ➔ ${arrName}`, size: "xxl", weight: "bold", margin: "md" },
      { type: "text", text: `${statusLabel}${isArrival ? '降落' : '出發'}：${displayTime}`, size: "xl", color: "#000000", weight: "bold", margin: "md" },
      { type: "text", text: `🏢 ${f.Terminal}航 / ${f.Gate || '-'}門${codeshare}`, size: "sm", color: "#888888", wrap: true, margin: "md" }
    ]
  };

  if (!dailyGroups.has(schedDate)) dailyGroups.set(schedDate, []);
  dailyGroups.get(schedDate).push({ sortTime: timeStr, content: flightRow });
}

// 4. 生成 Flex Carousel 結構並轉為字串輸出
const bubbles = Array.from(dailyGroups.entries())
  .sort((a, b) => a[0].localeCompare(b[0]))
  .map(([date, flights]) => {
    const sortedFlights = flights.sort((a, b) => a.sortTime.localeCompare(b.sortTime)).map(f => f.content);
    const bodyContents = [];
    sortedFlights.forEach((f, idx) => {
      if (idx > 0) bodyContents.push({ type: "separator" });
      bodyContents.push(f);
    });

    return {
      type: "bubble",
      size: "kilo",
      header: { type: "box", layout: "vertical", backgroundColor: "#004098", contents: [
        { type: "text", text: `📅 ${date} 航班動態`, color: "#ffffff", weight: "bold", size: "lg" }
      ]},
      body: { type: "box", layout: "vertical", spacing: "none", paddingAll: "0px", contents: bodyContents }
    };
  });

return {
  replyToken: replyToken,
  flexContentsString: JSON.stringify({
    type: "carousel",
    contents: bubbles
  }),
  altText: `✈️ ${mainAirlineName} ${airlineID}${flightNum} 查詢結果`
};

// 1. 取得 LINE 原始文字 (例如: "台鐵 中壢 羅東" 或 "台鐵 中壢到羅東")
let text = $('Line Messaging Trigger').item.json.message.text.trim();

// 2. 先拿掉「台鐵」關鍵字，簡化後續處理
text = text.replace(/^台鐵\s*/, "").trim(); 

// 3. 取得 API 回傳的所有車站清單
const allStations = $("取得全台車站清單").all().map(item => item.json).flat();

// 4. 解析起訖名稱邏輯
let depName = "", arrName = "";

// 使用正則表達式相容：空格、"到"、"至"、"-"、"往"
const parts = text.split(/[\s\-到至往]+/);

if (parts.length >= 2) {
  depName = parts[0].trim().replace(/臺/g, "台").replace(/站$/g, "");
  arrName = parts[1].trim().replace(/臺/g, "台").replace(/站$/g, "");
} else {
  throw new Error("格式不對喔！請輸入「台鐵 中壢 羅東」或「台鐵 中壢到羅東」");
}

// 5. 在清單中搜尋 StationID 的工具函數
const findId = (inputName) => {
  const station = allStations.find(s => {
    const apiName = s.StationName.Zh_tw.replace(/臺/g, "台").replace(/站$/g, "");
    return apiName === inputName;
  });
  return station ? station.StationID : null;
};

const depCode = findId(depName);
const arrCode = findId(arrName);

if (!depCode || !arrCode) {
  throw new Error(`找不到車站：${!depCode ? depName : arrName}`);
}

// 6. 取得今天日期 (台灣時間)
const taiwanDate = new Date(new Date().getTime() + 8 * 3600000).toISOString().split('T')[0];

return {
  depCode,
  arrCode,
  depName,
  arrName,
  queryDate: taiwanDate
};

// 1. 取得基礎資料
const stationInfo = $("動態比對車站代碼").first().json;

// 2. 格式化日期與時間
const webDate = stationInfo.queryDate.replace(/-/g, "/");
const nowTime = new Date(new Date().getTime() + 8 * 3600000);
const nowStr = nowTime.toISOString().split('T')[1].substring(0, 5); 

// 3. 取得 API 資料
const scheduleTrains = $("呼叫台鐵時刻表API").all().map(i => i.json);
const liveBoard = $("查詢誤點").all().map(i => i.json);

// 4. 定義台鐵官網連結 (encodeURI 處理)
const rawManualUrl = `https://www.railway.gov.tw/tra-tip-web/tip/tip001/tip112/gobytime?startStation=${stationInfo.depCode}-${stationInfo.depName}&endStation=${stationInfo.arrCode}-${stationInfo.arrName}&rideDate=${webDate}&transfer=ONE&trainTypeList=ALL&startOrEndTime=true`;
const manualSearchUrl = encodeURI(rawManualUrl);

// 5. 過濾接下來 3 班車
const upcoming = scheduleTrains
  .filter(t => t.OriginStopTime.DepartureTime > nowStr)
  .sort((a, b) => a.OriginStopTime.DepartureTime.localeCompare(b.OriginStopTime.DepartureTime))
  .slice(0, 3);

// 6. 建立時刻表行
const rows = upcoming.map(t => {
  const trainNo = t.DailyTrainInfo.TrainNo;
  const typeName = t.DailyTrainInfo.TrainTypeName.Zh_tw.replace(/\(.*\)/, "");
  const depTime = t.OriginStopTime.DepartureTime;
  const arrTime = t.DestinationStopTime.ArrivalTime;

  const liveInfo = liveBoard.find(l => l.TrainNo === trainNo);
  let delayText = "準點", delayColor = "#008000"; 
  if (liveInfo && liveInfo.DelayTime > 0) {
    delayText = `誤${liveInfo.DelayTime}`;
    delayColor = "#FF0000"; 
  }

  const stopStationUrl = encodeURI(`https://www.railway.gov.tw/tra-tip-web/tip/tip001/tip112/gobytrainno?rideDate=${webDate}&trainNo=${trainNo}`);

  return {
    type: "box", layout: "vertical", margin: "lg",
    contents: [
      {
        type: "box", layout: "horizontal", alignItems: "center",
        contents: [
          { type: "text", text: trainNo, size: "sm", color: "#555555", flex: 10, weight: "bold" },
          { type: "text", text: typeName, size: "sm", color: "#888888", flex: 10 },
          { type: "text", text: delayText, size: "xs", color: delayColor, flex: 5 },
          { type: "text", text: depTime, size: "md", color: "#000000", flex: 10, align: "center", weight: "bold" },
          { type: "text", text: arrTime, size: "md", color: "#aaaaaa", flex: 10, align: "end" }
        ]
      },
      {
        type: "button", height: "sm", style: "secondary", color: "#f0f0f0", margin: "sm",
        action: {
          type: "uri", label: "查看停靠站",
          uri: stopStationUrl
        }
      }
    ]
  };
});

// 7. 建立 Flex Bubble 物件
const flexBubble = {
  type: "bubble",
  header: {
    type: "box", layout: "vertical",
    contents: [{ type: "text", text: "台鐵時刻表", weight: "bold", color: "#ffffff", size: "xl", align: "center" }],
    backgroundColor: "#005EB8"
  },
  body: {
    type: "box", layout: "vertical",
    contents: [
      {
        type: "box", layout: "horizontal", justifyContent: "center", alignItems: "center",
        contents: [
          { type: "text", text: stationInfo.depName, size: "3xl", weight: "bold", align: "end", flex: 1 },
          { type: "text", text: "→", size: "3xl", weight: "bold", color: "#005EB8", flex: 0, margin: "md" },
          { type: "text", text: stationInfo.arrName, size: "3xl", weight: "bold", align: "start", flex: 1, margin: "md" }
        ]
      },
      { type: "separator", margin: "lg" },
      ...(upcoming.length === 0 ? [
        { type: "text", text: `❌ ${nowStr} 後無直達班次`, margin: "xl", align: "center", color: "#FF0000", weight: "bold" }
      ] : [
        {
          type: "box", layout: "horizontal", margin: "md",
          contents: [
            { type: "text", text: "車次", size: "sm", color: "#aaaaaa", flex: 10 },
            { type: "text", text: "車種", size: "sm", color: "#aaaaaa", flex: 10 },
            { type: "text", text: "狀態", size: "sm", color: "#aaaaaa", flex: 5 },
            { type: "text", text: "發車", size: "sm", color: "#aaaaaa", flex: 10, align: "center" },
            { type: "text", text: "抵達", size: "sm", color: "#aaaaaa", flex: 10, align: "end" }
          ]
        },
        ...rows
      ])
    ]
  },
  footer: {
    type: "box", layout: "vertical",
    contents: [
      {
        type: "button", style: "link", height: "sm",
        action: {
          type: "uri", label: "手動查詢更多班次 (官網)",
          uri: manualSearchUrl
        }
      }
    ]
  }
};

// 最終輸出：將 flex 轉成字串，解決 [object Object] 報錯
return {
  replyToken: $("Line Messaging Trigger").first().json.replyToken,
  flexJson: JSON.stringify(flexBubble), 
  altText: `台鐵時刻表: ${stationInfo.depName}→${stationInfo.arrName}`
};

// 1. 定義高鐵站名對照表
const hsrStationList = [
  { "ID": "0990", "Name": "南港" }, { "ID": "1000", "Name": "台北" },
  { "ID": "1010", "Name": "板橋" }, { "ID": "1020", "Name": "桃園" },
  { "ID": "1030", "Name": "新竹" }, { "ID": "1035", "Name": "苗栗" },
  { "ID": "1040", "Name": "台中" }, { "ID": "1043", "Name": "彰化" },
  { "ID": "1047", "Name": "雲林" }, { "ID": "1050", "Name": "嘉義" },
  { "ID": "1060", "Name": "台南" }, { "ID": "1070", "Name": "左營" }
];

// 2. 縣市別名對照
const cityAlias = {
  "高雄": "左營", "新北": "板橋", "臺北": "台北", "臺中": "台中", "臺南": "台南"
};

// 3. 【核心修正】解析 Line 輸入文字
const rawText = $("Line Messaging Trigger").first().json.message.text || "";

// 先移除「高鐵」，再把「到」、「至」、「-」或「~」替換成空格，最後移除多餘空格
const cleanText = rawText
  .replace(/高鐵/g, "")
  .replace(/[到至\-~]/g, " ") 
  .trim();

const parts = cleanText.split(/\s+/);

let depInput = parts[0] || "";
let arrInput = parts[1] || "";

// 4. 執行名稱轉換
depInput = cityAlias[depInput] || depInput;
arrInput = cityAlias[arrInput] || arrInput;

// 5. 比對代碼
const depStation = hsrStationList.find(s => s.Name.includes(depInput));
const arrStation = hsrStationList.find(s => s.Name.includes(arrInput));

if (!depStation || !arrStation) {
  throw new Error(`找不到車站資訊，解析結果：${depInput} -> ${arrInput}`);
}

// 6. 準備輸出資料
const taipeiTime = new Date(new Date().getTime() + 8 * 3600000);
const todayStr = taipeiTime.toISOString().split('T')[0];

return {
  depCode: depStation.ID,
  depName: depStation.Name,
  arrCode: arrStation.ID,
  arrName: arrStation.Name,
  queryDate: todayStr,
  manualSearchUrl: encodeURI(`https://www.thsrc.com.tw/ArticleContent/a3b630bb-106e-4c18-8737-ad99a4abb387?startStation=${depStation.Name}&endStation=${arrStation.Name}&outboundDate=${todayStr}`)
};

/**
 * 高鐵即時座位 Flex Message 組裝代碼
 * 適用流程：時刻表 -> 篩選前三班 -> 查詢座位API -> [本節點]
 */

// 1. 取得「查詢座位API」的原始資料 (處理空值)
const seatInput = $input.all();
const seatData = (seatInput.length > 0 && seatInput[0].json.AvailableSeats) ? seatInput[0].json.AvailableSeats : [];

// 2. 跨節點取得「篩選班次」提供的班次資訊與車站名稱
// 注意：請確保你的篩選節點名稱確實叫做 "篩選班次"
const prevNodeData = $("篩選班次").first().json;
const upcoming = prevNodeData.upcoming || [];
const stationInfo = prevNodeData.stationInfo || { depName: "未知", arrName: "未知", depCode: "" };

// 3. 處理每一行班次的顯示邏輯
const rows = upcoming.map(t => {
  const trainNo = t.DailyTrainInfo.TrainNo;
  // 在座位清單中找這班車
  const seatInfo = seatData.find(s => String(s.TrainNo) === String(trainNo));

  let seatIcon = "⚪"; // 預設灰色：代表 API 尚未提供該班次即時資料
  let statusColor = "#aaaaaa";

  if (seatInfo && seatInfo.StopStations) {
    // 比對該班次在你「出發站」的狀態
    const stop = seatInfo.StopStations.find(ss => String(ss.StationID) === String(stationInfo.depCode));
    const status = stop ? stop.Status : null;

    if (status === "O") { seatIcon = "🟢"; statusColor = "#00b900"; }
    else if (status === "L") { seatIcon = "🟡"; statusColor = "#ffcc00"; }
    else if (status === "X") { seatIcon = "🔴"; statusColor = "#ff0000"; }
  }

  return {
    type: "box",
    layout: "horizontal",
    margin: "lg",
    alignItems: "center",
    contents: [
      { type: "text", text: `${seatIcon} ${trainNo}`, size: "sm", color: "#555555", flex: 1, weight: "bold" },
      { type: "text", text: t.OriginStopTime.DepartureTime, size: "md", color: "#F58220", flex: 1, align: "center", weight: "bold" },
      { type: "text", text: "→", size: "sm", color: "#aaaaaa", flex: 0 },
      { type: "text", text: t.DestinationStopTime.ArrivalTime, size: "md", color: "#000000", flex: 1, align: "end" }
    ]
  };
});

// 4. 設定底部提示文字 (若 API 回傳空陣列則顯示警示)
const isDataEmpty = seatData.length === 0;
const footerText = isDataEmpty ? "⚠️ 部分班次尚未開放即時查詢" : "🟢有位 🟡位少 🔴客滿";

// 5. 組裝最終的輸出物件 (供 LINE 節點使用)
return {
  replyToken: $("Line Messaging Trigger").first().json.replyToken,
  flexJson: JSON.stringify({
    type: "bubble",
    header: {
      type: "box",
      layout: "vertical",
      backgroundColor: "#F58220",
      contents: [
        { type: "text", text: "台灣高鐵即時座位", weight: "bold", color: "#ffffff", size: "lg", align: "center" }
      ]
    },
    body: {
      type: "box",
      layout: "vertical",
      contents: [
        {
          type: "box",
          layout: "horizontal",
          justifyContent: "center",
          alignItems: "center",
          contents: [
            { type: "text", text: stationInfo.depName, size: "xl", weight: "bold", align: "end", flex: 1 },
            { type: "text", text: "→", size: "xl", weight: "bold", color: "#F58220", flex: 0, margin: "md" },
            { type: "text", text: stationInfo.arrName, size: "xl", weight: "bold", align: "start", flex: 1, margin: "md" }
          ]
        },
        { type: "separator", margin: "md" },
        // 如果沒班次，顯示查無班次，否則顯示 rows
        ...(rows.length === 0 
          ? [{ type: "text", text: "❌ 此時段已無後續班次", margin: "xl", align: "center", color: "#FF0000" }] 
          : rows)
      ]
    },
    footer: {
      type: "box",
      layout: "vertical",
      contents: [
        { type: "text", text: footerText, size: "xs", color: "#aaaaaa", align: "center" }
      ]
    }
  }),
  altText: `高鐵時刻表: ${stationInfo.depName}→${stationInfo.arrName}`
};

// 1. 取得車站資訊 (從 Code in JavaScript2 抓取)
const stationInfo = $("Code in JavaScript2").first().json;
// 2. 取得時刻表清單 (從 呼叫高鐵時刻表API 抓取所有 items)
const allTrains = $input.all().map(i => i.json);

// 3. 取得台北目前時間 (UTC+8)
const now = new Date(new Date().getTime() + 8 * 3600000);
const nowStr = now.toISOString().split('T')[1].substring(0, 5); 

// 4. 篩選出出發時間大於現在的班次，並排序取前三名
const upcoming = allTrains
  .filter(t => t.OriginStopTime.DepartureTime > nowStr)
  .sort((a, b) => a.OriginStopTime.DepartureTime.localeCompare(b.OriginStopTime.DepartureTime))
  .slice(0, 3);

// 5. 生成給下一關「查詢座位API」使用的篩選語法
// 例如: TrainNo eq '0603' or TrainNo eq '0609'
const filterQuery = upcoming.map(t => `TrainNo eq '${t.DailyTrainInfo.TrainNo}'`).join(' or ');

return {
  upcoming,
  filterQuery,
  stationInfo
};
